<?php require_once __DIR__.'/../includes/db.php'; require_once __DIR__.'/../includes/auth.php'; require_login(); $id=(int)($_GET['id']??0); $stmt=$mysqli->prepare("SELECT b.*,s.slot_number FROM bookings b JOIN slots s ON s.id=b.slot_id WHERE b.id=? AND b.user_id=?"); $uid=$_SESSION['user']['id']; $stmt->bind_param('ii',$id,$uid); $stmt->execute(); $b=$stmt->get_result()->fetch_assoc(); if(!$b){flash('error','Booking not found.');header('Location: dashboard.php');exit;} if($_SERVER['REQUEST_METHOD']==='POST' && $b['status']==='pending_payment'){ $method=$_POST['method']; $mysqli->begin_transaction(); try{$stmt=$mysqli->prepare("INSERT INTO payments(booking_id,amount,method,status) VALUES(?,?,?,'paid')");$stmt->bind_param('ids',$id,$b['parking_amount'],$method);$stmt->execute();$stmt=$mysqli->prepare("UPDATE bookings SET status='paid' WHERE id=?");$stmt->bind_param('i',$id);$stmt->execute();$mysqli->commit();flash('success','Payment successful. Your QR entry pass is ready.');header('Location: booking.php?id='.$id);exit;}catch(Throwable $e){$mysqli->rollback();flash('error','Payment could not be recorded.');} } $page_title='Payment'; require __DIR__.'/../includes/header.php'; ?>
<div class="row justify-content-center"><div class="col-md-6"><div class="card shadow-sm border-0"><div class="card-body p-4"><h2>Confirm payment</h2><p>Slot <b><?=e($b['slot_number'])?></b> · <?=date('d M, h:i A',strtotime($b['start_time']))?></p><div class="display-6 mb-3">₹<?=number_format($b['parking_amount'],2)?></div><?php if($b['status']==='pending_payment'): ?><form method="post"><label class="form-label">Payment method</label><select class="form-select mb-3" name="method"><option>UPI (Demo)</option><option>Card (Demo)</option><option>Cash (Demo)</option></select><button class="btn btn-success w-100">Pay now (simulation)</button></form><?php else:?><a class="btn btn-primary" href="booking.php?id=<?=$id?>">View booking</a><?php endif;?></div></div></div></div><?php require __DIR__.'/../includes/footer.php'; ?>
